head.b:skin:
*{
  box-sizing:border-box;
}

html{
  scroll-behavior:smooth;
}

body{
  margin:0;
  padding:0;
  background:#f5f6f8;
  color:#151515;
  font-family:Arial,Helvetica,sans-serif;
}

a{
  text-decoration:none;
  color:inherit;
}

img{
  max-width:100%;
}

.container{
  width:94%;
  max-width:1250px;
  margin:auto;
}

/* TOP BAR */

.topbar{
  background:#111827;
  color:#fff;
  font-size:13px;
}

.topbar-inner{
  min-height:38px;
  display:flex;
  align-items:center;
  justify-content:space-between;
}

.topbar span{
  opacity:.9;
}

/* HEADER */

.header{
  background:#fff;
  border-bottom:1px solid #e5e7eb;
  position:sticky;
  top:0;
  z-index:999;
}

.header-inner{
  min-height:78px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:20px;
}

.logo{
  display:flex;
  align-items:center;
  gap:10px;
  min-width:240px;
}

.logo-icon{
  width:48px;
  height:48px;
  border-radius:10px;
  background:#e30613;
  color:#fff;
  display:flex;
  align-items:center;
  justify-content:center;
  font-size:25px;
  font-weight:bold;
}

.logo-text strong{
  display:block;
  font-size:18px;
  line-height:20px;
  color:#111827;
}

.logo-text small{
  color:#e30613;
  font-size:11px;
  font-weight:bold;
}

.search-box{
  flex:1;
  max-width:560px;
  height:46px;
  border:1px solid #d8dce2;
  border-radius:7px;
  display:flex;
  background:#fff;
  overflow:hidden;
}

.search-box input{
  flex:1;
  border:0;
  outline:0;
  padding:0 16px;
  font-size:14px;
}

.search-box button{
  width:58px;
  border:0;
  background:#e30613;
  color:#fff;
  cursor:pointer;
  font-size:18px;
}

.header-actions{
  display:flex;
  align-items:center;
  gap:10px;
}

.action-btn{
  border:1px solid #ddd;
  background:#fff;
  padding:11px 14px;
  border-radius:7px;
  font-weight:bold;
  font-size:13px;
}

.whatsapp-btn{
  background:#168c42;
  color:#fff;
  border:0;
}

/* NAV */

.nav{
  background:#fff;
  border-bottom:1px solid #e5e7eb;
}

.nav-inner{
  display:flex;
  align-items:center;
  gap:30px;
  min-height:48px;
}

.nav a{
  font-size:14px;
  font-weight:bold;
}

.nav a:hover{
  color:#e30613;
}

/* HERO */

.hero{
  padding:25px 0;
}

.hero-box{
  min-height:360px;
  border-radius:14px;
  overflow:hidden;
  position:relative;
  background:
    linear-gradient(90deg,rgba(5,10,20,.96),rgba(5,10,20,.65),rgba(5,10,20,.15)),
    url('https://images.unsplash.com/photo-1558981806-ec527fa84c39?auto=format&fit=crop&w=1400&q=80');
  background-size:cover;
  background-position:center;
  display:flex;
  align-items:center;
}

.hero-content{
  width:60%;
  padding:45px;
  color:#fff;
}

.hero-content .tag{
  display:inline-block;
  background:#e30613;
  padding:8px 13px;
  border-radius:4px;
  font-size:12px;
  font-weight:bold;
  margin-bottom:14px;
}

.hero-content h1{
  font-size:42px;
  line-height:1.08;
  margin:0 0 15px;
}

.hero-content p{
  font-size:16px;
  line-height:1.6;
  color:#e5e7eb;
}

.hero-buttons{
  display:flex;
  gap:12px;
  margin-top:22px;
}

.red-btn{
  background:#e30613;
  color:#fff;
  padding:13px 22px;
  border-radius:6px;
  font-weight:bold;
  display:inline-block;
}

.white-btn{
  background:#fff;
  color:#111827;
  padding:13px 22px;
  border-radius:6px;
  font-weight:bold;
  display:inline-block;
}

/* BRANDS */

.section{
  padding:18px 0 30px;
}

.section-head{
  display:flex;
  justify-content:space-between;
  align-items:center;
  margin-bottom:17px;
}

.section-head h2{
  margin:0;
  font-size:24px;
}

.section-head a{
  color:#e30613;
  font-size:13px;
  font-weight:bold;
}

.brand-grid{
  display:grid;
  grid-template-columns:repeat(6,1fr);
  gap:15px;
}

.brand-card{
  background:#fff;
  border:1px solid #e7e9ed;
  border-radius:10px;
  padding:2px 10px;
  text-align:center;
  transition:.2s;
}

.brand-card:hover{
  transform:translateY(-3px);
  box-shadow:0 8px 25px rgba(0,0,0,.08);
}

.brand-logo{
  height:100%;
  display:flex;
  align-items:center;
  justify-content:center;
  font-size:24px;
  font-weight:900;
  margin-bottom:10px;
}

.brand-card span{
  font-size:13px;
  display:none; 
  color:#666;
}

/* CATEGORY PAGE */
.category-page-head{
  display:none;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  margin-bottom:18px;
}
.category-page-head h1{
  margin:0;
  font-size:24px;
  font-weight:900;
}
.category-back{
  display:inline-block;
  text-decoration:none;
  background:#111827;
  color:#fff;
  padding:10px 14px;
  border-radius:8px;
  font-weight:700;
  font-size:13px;
}
body.category-mode .hero,
body.category-mode #brands,
body.category-mode #categories{
  display:none !important;
}
body.category-mode .category-page-head{
  display:flex;
}

/* CATEGORIES */

.category-grid{
  display:grid;
  grid-template-columns:repeat(6,1fr);
  gap:12px;
}

.category{
  background:#fff;
  border:1px solid #e5e7eb;
  border-radius:9px;
  padding:18px 8px;
  text-align:center;
  font-weight:bold;
  font-size:13px;
}

.category-icon{
  font-size:28px;
  margin-bottom:8px;
}

/* FEATURES */

.features{
  background:#111827;
  color:#fff;
  padding:25px 0;
  margin-top:15px;
}

.feature-grid{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:15px;
}

.feature{
  display:flex;
  align-items:center;
  gap:12px;
}

.feature-icon{
  width:45px;
  height:45px;
  border-radius:50%;
  background:#e30613;
  display:flex;
  align-items:center;
  justify-content:center;
  font-size:20px;
}

.feature strong{
  display:block;
  font-size:14px;
}

.feature small{
  color:#aaa;
}

/* FOOTER */

.footer{
  background:#0b0f16;
  color:#fff;
  padding:40px 0 20px;
}

.footer-grid{
  display:grid;
  grid-template-columns:2fr 1fr 1fr 1.5fr;
  gap:35px;
}

.footer h3{
  font-size:17px;
  margin-top:0;
}

.footer p,
.footer a{
  color:#aeb4bf;
  font-size:13px;
  line-height:1.8;
}

.footer a:hover{
  color:#fff;
}

.copyright{
  border-top:1px solid #252b35;
  margin-top:30px;
  padding-top:18px;
  text-align:center;
  color:#777;
  font-size:12px;
}

/* BLOGGER */

#main-wrapper{
  width:100%;
}

.blog-posts{
  display:none;
}

#sidebar-wrapper{
  display:none;
}

/* MOBILE */

.mobile-menu{
  display:none;
}

@media(max-width:900px){

  .header-inner{
    flex-wrap:wrap;
    padding:12px 0;
  }

  .logo{
    min-width:auto;
  }

  .search-box{
    order:3;
    flex-basis:100%;
    max-width:none;
  }

  .nav-inner{
    overflow-x:auto;
    white-space:nowrap;
  }

  .hero-content{
    width:85%;
    padding:30px;
  }

  .hero-content h1{
    font-size:34px;
  }

  .product-grid{
    grid-template-columns:repeat(3,1fr);
  }

  .category-grid{
    grid-template-columns:repeat(3,1fr);
  }

  .feature-grid{
    grid-template-columns:repeat(3,1fr);
  }

  .footer-grid{
    grid-template-columns:repeat(2,1fr);
  }
}

@media(max-width:600px){

  .topbar-inner{
    justify-content:center;
  }

  .topbar span:last-child{
    display:none;
  }

  .header-actions .action-btn{
    display:none;
  }

  .hero-box{
    min-height:430px;
  }

  .hero-content{
    width:100%;
    padding:25px;
  }

  .hero-content h1{
    font-size:30px;
  }

  .hero-content p{
    font-size:14px;
  }

  .brand-grid{
    grid-template-columns:repeat(3,1fr);
  }

  .category-grid{
    grid-template-columns:repeat(3,1fr);
  }

  .product-grid{
    grid-template-columns:repeat(3,1fr);
    gap:10px;
  }

  .product-img{
    height:140px;
  }

  .product-info{
    padding:10px;
  }

  .product-name{
    font-size:13px;
  }

  .product-price{
    font-size:15px;
  }

  .feature-grid{
    grid-template-columns:1fr;
  }

  .footer-grid{
    grid-template-columns:1fr;
  }

  .section-head h2{
    font-size:20px;
  }

  .hero-buttons{
    flex-direction:column;
  }

  .red-btn,
  .white-btn{
    text-align:center;
  }
}
.bike-filter{
  display:flex;
  gap:10px;
  overflow-x:auto;
  margin-bottom:20px;
  padding-bottom:5px;
}

.filter-btn{
  border:1px solid #ddd;
  background:#fff;
  color:#222;
  padding:10px 22px;
  border-radius:6px;
  font-weight:bold;
  cursor:pointer;
  white-space:nowrap;
}

.filter-btn:hover,
.filter-btn.active{
  background:#e30613;
  color:#fff;
  border-color:#e30613;
}

.product-model{
  color:#777;
  font-size:11px;
  margin:4px 0;
}

.product-img{
  background:#fff;
}

.product-img img{
  transition:.3s;
}

.product:hover .product-img img{
  transform:scale(1.05);
}

.header-icons{
  display:flex;
  gap:15px;
  align-items:center;
}
.header-icons a{
  font-size:25px;
  color:#111;
  text-decoration:none;
}

.brand-card{
  padding:8px !important;
  min-height:75px !important;
  height:75px !important;
}

.brand-card .brand-logo{
  height:100% !important;
  width:100%;
  display:flex;
  align-items:center;
  justify-content:center;
}

.brand-card .brand-logo img{
  max-height:48px !important;
  width:100% !important;
  height:100% !important;
  max-width:100% !important;
  object-fit:contain !important;
}

.product-grid{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:16px;
}

.product{
  background:#fff;
  border:1px solid #eee;
  border-radius:10px;
  overflow:hidden;
  box-shadow:0 2px 8px rgba(0,0,0,0.06);
}

.add-cart-btn{
  width:100%;
  padding:11px;
  margin-top:8px;
  border:1px solid #e30613;
  border-radius:6px;
  background:#fff;
  color:#e30613;
  font-weight:bold;
  cursor:pointer;
}

.add-cart-btn:hover{
  background:#e30613;
  color:#fff;
}

.product-img{
  width:100%;
  aspect-ratio:1/1;
  overflow:hidden;
  background:#f5f5f5;
}

.product-img img{
  width:100%;
  height:100%;
  object-fit:cover;
  display:block;
}

.product-info{
  padding:12px;
}

.product-brand{
  font-size:12px;
  font-weight:700;
  color:#e60012;
  margin-bottom:5px;
}

.product-name{
  font-size:15px;
  font-weight:600;
  line-height:1.3;
  min-height:40px;
}

.product-price{
  font-size:13px;
  margin:8px 0;
}

.order-btn{
  display:block;
  width:100%;
  box-sizing:border-box;
  background:#25D366;
  color:#fff !important;
  text-align:center;
  padding:9px 6px;
  border-radius:6px;
  text-decoration:none;
  font-size:13px;
  font-weight:600;
}

@media (max-width:700px){
  .product-grid{
    grid-template-columns:repeat(3,1fr);
    gap:10px;
  }

  .product-info{
    padding:9px;
  }

  .product-name{
    font-size:13px;
    min-height:34px;
  }

  .product-price{
    font-size:12px;
  }

  .order-btn{
    font-size:12px;
    padding:8px 4px;
  }
}

@media (max-width:380px){
  .product-grid{
    gap:8px;
  }

  .product-name{
    font-size:12px;
  }
}

.brand-grid .brand-card{
  width:100% !important;
  height:100% !important;
  min-height:70px !important;
  padding:5px !important;
  margin:0 auto !important;
  box-sizing:border-box !important;
}

.brand-grid .brand-card .brand-logo{
  height:100% !important;
  width:100% !important;
}

.brand-grid .brand-card .brand-logo img{
  width:auto !important;
  height:42px !important;
  max-width:80px !important;
  max-height:42px !important;
  object-fit:contain !important;
}

.brand-grid .brand-card span{
  font-size:10px !important;
  line-height:12px !important;
}

body.script:
//

const SHEET_ID = '1Pd2M3MEXxBo_l7RIUoWtX7QD3OsMwk64RYlA5lzv0ug';
const SHEET_NAME = 'Sheet1';


function toggleSearch() {
  var panel = document.getElementById('searchPanel');
  if (panel) {
    panel.style.display = panel.style.display === 'none' ? 'block' : 'none';
  }
}
var cartList = [];

function addToCart(name, brand, model) {
  var existingItem = cartList.find(function(item) {
    return item.name === name;
  });

  if (existingItem) {
    existingItem.qty += 1;
  } else {
    cartList.push({ name: name, brand: brand || '', model: model || '', qty: 1 });
  }

  updateCartCount();
  alert(name + ' added to cart!');
}

function updateCartCount() {
  var countEl = document.getElementById('cartCount');
  if (countEl) {
    var totalCount = cartList.reduce(function(sum, item) {
      return sum + item.qty;
    }, 0);
    countEl.innerText = totalCount;
  }
}

function openCart() {
  var modal = document.getElementById('cartModal');
  var listContainer = document.getElementById('cartItemsList');

  if (!modal || !listContainer) return;

  if (cartList.length === 0) {
    listContainer.innerHTML = '<p style="text-align:center; color:#777; margin-top:30px;">Your cart is empty!</p>';
  } else {
    var html = '<ul style="list-style:none; padding:0; margin:0;">';
    cartList.forEach(function(item, index) {
      html += '<li style="display:flex; justify-content:space-between; align-items:center; padding:12px 0; border-bottom:1px solid #eee;">' +
                '<div style="flex:1;">' +
                  '<strong style="font-size:14px; display:block;">' + item.name + '</strong>' +
                '</div>' +
                '<div style="display:flex; align-items:center; gap:8px;">' +
                  '<button onclick="changeQty(' + index + ', -1)" style="background:#f0f0f0; border:1px solid #ccc; width:28px; height:28px; border-radius:4px; font-weight:bold; cursor:pointer;">-</button>' +
                  '<span style="font-weight:bold; width:20px; text-align:center;">' + item.qty + '</span>' +
                  '<button onclick="changeQty(' + index + ', 1)" style="background:#f0f0f0; border:1px solid #ccc; width:28px; height:28px; border-radius:4px; font-weight:bold; cursor:pointer;">+</button>' +
                  '<button onclick="removeFromCart(' + index + ')" style="color:red; background:none; border:none; cursor:pointer; font-size:16px; margin-left:5px;">🗑️</button>' +
                '</div>' +
              '</li>';
    });
    html += '</ul>';
    listContainer.innerHTML = html;
  }

  modal.style.display = 'flex';
}

function changeQty(index, change) {
  cartList[index].qty += change;

  if (cartList[index].qty <= 0) {
    cartList.splice(index, 1);
  }

  updateCartCount();
  openCart();
}

function closeCart() {
  var modal = document.getElementById('cartModal');
  if (modal) modal.style.display = 'none';
}

function removeFromCart(index) {
  cartList.splice(index, 1);
  updateCartCount();
  openCart();
}

function sendWhatsAppOrder() {
  if (cartList.length === 0) {
    alert('आपका कार्ट खाली है! पहले उत्पाद जोड़ें।');
    return;
  }

  var message = "Hello SHREE SONAGARA AUTO PARTS,\nI want to order the following items:\n\n";
  cartList.forEach(function(item, index) {
    message += (index + 1) + ". " + item.name + " (Qty: " + item.qty + ")\n";
  });

  var whatsappNumber = "918460650603";
  var whatsappUrl = "https://wa.me/" + whatsappNumber + "?text=" + encodeURIComponent(message);

  window.open(whatsappUrl, '_blank');
}



function searchProducts(){
  var input = document.getElementById('siteSearch');
  if(!input) return;

  var filter = input.value.toLowerCase().trim();
  var products = document.querySelectorAll('.product');

  products.forEach(function(product){
    var text = product.textContent.toLowerCase();
    if(filter === '' || text.indexOf(filter) !== -1){
      product.style.display = '';
    } else {
      product.style.display = 'none';
    }
  });
}

function filterModel(model){
  var products = document.querySelectorAll('.product');
  products.forEach(function(product){
    if(model === 'all'){
      product.style.display = '';
    } else if(product.getAttribute('data-model') === model){
      product.style.display = '';
    } else {
      product.style.display = 'none';
    }
  });
}
async function loadProductsFromSheet() {
  const grid = document.getElementById('productGrid');
  if (!grid) return;

  // 1. URL से चुनी हुई कैटेगरी लें (?cat=brake)
  const urlParams = new URLSearchParams(window.location.search);
  const selectedCategory = urlParams.get('cat');

  // 2. Google Sheet का URL बनाएं
  const url = 'https://docs.google.com/spreadsheets/d/' + SHEET_ID + '/gviz/tq?tqx=out:json&sheet=' + encodeURIComponent(SHEET_NAME);

  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error('Google Sheet response error: ' + response.status);

    const text = await response.text();
    const start = text.indexOf('{');
    const end = text.lastIndexOf('}');
    if (start === -1 || end === -1) throw new Error('Invalid Google Sheet response');

    const json = JSON.parse(text.substring(start, end + 1));
    if (!json.table || !json.table.rows) throw new Error('No table data found in Sheet');

    const rows = json.table.rows;
    grid.innerHTML = '';

    rows.forEach(function(row) {
      const c = row.c || [];
      const productName = c[0] && c[0].v != null ? c[0].v : ''; // Col A (Name)
      const brand       = c[1] && c[1].v != null ? c[1].v : ''; // Col B (Brand)
      const category    = c[2] && c[2].v != null ? c[2].v : ''; // Col C (Category)
      const model       = c[3] && c[3].v != null ? c[3].v : ''; // Col D (Model)
      const price       = c[4] && c[4].v != null ? c[4].v : 'Price On Request'; // Col E (Price)
      const image       = c[5] && c[5].v != null ? c[5].v : 'https://via.placeholder.com/500x400?text=Auto+Parts'; // Col F (Image)

      if (!productName) return;

      // 3. कैटेगरी फ़िल्टर चेक करें
      if (selectedCategory && category.toString().trim().toLowerCase() !== selectedCategory.trim().toLowerCase()) {
        return;
      }

      const product = document.createElement('div');
      product.className = 'product';
      product.dataset.brand = brand;
      product.dataset.category = category;
      product.dataset.model = model;

      const message = 'I want ' + productName + (model ? ' for ' + model : '');

      // Single quotes एरर से बचने के लिए नाम साफ़ करें
      const safeName = productName.replace(/'/g, "\\'");
      const safeBrand = brand.replace(/'/g, "\\'");
      const safeModel = model.replace(/'/g, "\\'");

      // 4. Product HTML तैयार करें
      product.innerHTML = 
        '<div class="product-img">' +
          '<img src="' + image + '" alt="' + productName + '" loading="lazy">' +
        '</div>' +
        '<div class="product-info">' +
          '<div class="product-brand">' + brand + '</div>' +
          '<div class="product-name">' + productName + '</div>' +
          '<div class="product-model">' + model + '</div>' +
          '<div class="product-price">₹' + price + '</div>' +
          '<button class="add-cart-btn" type="button" onclick="addToCart(\'' + safeName + '\', \'' + safeBrand + '\', \'' + safeModel + '\')">Add to Cart</button>' +
          '<a class="order-btn" href="https://wa.me/918460650603?text=' + encodeURIComponent(message) + '" target="_blank">WhatsApp Order</a>' +
        '</div>';

      grid.appendChild(product);
    });

  } catch (error) {
    console.error('Sheet loading error:', error);
  }
}
document.addEventListener('DOMContentLoaded', loadProductsFromSheet);
loadProductsFromSheet();

document.addEventListener('DOMContentLoaded', function(){
  // Floating WhatsApp Button
  var wa = document.createElement('a');
  wa.href = 'https://wa.me/918460650603';
  wa.target = '_blank';
  wa.innerHTML = '💬';
  wa.style.position = 'fixed';
  wa.style.right = '18px';
